/*
  pingoscope — RECEIVER (CYD ESP32-32E / ST7789)
  Dark cardio-sweep ping monitor.
    L1: IP (big)
    L2: country + ASN (big, word-truncated to one line)
    L3: ticker band (recent ms values; current value highlighted)
    rest: cardio SWEEP graph (left->right, autoscaled, hard cap 300ms)
  BOOT toggles a raw debug view. Display library files live in this folder.
  Board: ESP32 Dev Module.
*/
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>
#include <string.h>
#include <stdlib.h>

#define TFT_CS 15
#define TFT_DC 2
#define TFT_RST -1
#define TFT_BL 21
Adafruit_ST7789 tft(TFT_CS, TFT_DC, TFT_RST);

#define LED_R 22
#define LED_G 16
#define LED_B 17
inline void ledOff(){ digitalWrite(LED_R,HIGH); digitalWrite(LED_G,HIGH); digitalWrite(LED_B,HIGH); }
inline void ledGreen(bool on){ digitalWrite(LED_G,on?LOW:HIGH); }
inline void ledRed(bool on){ digitalWrite(LED_R,on?LOW:HIGH); }

#define BTN 0
#define ESPNOW_CHANNEL 1
#define MSG_PROBE 1
#define MSG_NETINFO 2
#define RTT_CAP 300            // hard Y-axis cap (ms)

typedef struct __attribute__((packed)) { uint8_t type; uint32_t seq; uint16_t rtt_ms; uint8_t status; } probe_t;
typedef struct __attribute__((packed)) { uint8_t type; char ip[16]; char country[4]; char asn[40]; } netinfo_t;

const char* statusLabel(uint8_t s){ switch(s){case 0:return "OK";case 1:return "PING TIMEOUT";case 2:return "NO IP";default:return "LINK DOWN";} }

// ---- colors (dark theme; tweak freely) ----
#define COL_BG        0x0000   // black
#define COL_IP        0xFFFF   // white
#define COL_GEO       0x07FF   // cyan
#define COL_TICK_BG   0x2124   // dark grey band
#define COL_TICK_TXT  0xFD20   // amber (history)
#define COL_TICK_CUR  0xFFFF   // white (current value)
#define COL_PLOT_BG   0x0009   // dim navy (graph area divider)
#define COL_TRACE     0x07E0   // green
#define COL_FAIL      0xF800   // red
#define COL_AXIS      0x8410   // grey

// ---- layout (landscape 320x240) ----
#define IP_Y    2
#define GEO_Y   28
#define TICK_Y  50
#define TICK_H  18
#define PLOT_X0 2
#define PLOT_Y0 (TICK_Y + TICK_H + 3)   // ~71
#define PLOT_W  316
#define PLOT_Y1 238
#define PLOT_H  (PLOT_Y1 - PLOT_Y0)
#define HIST    PLOT_W                  // one column per sample
#define SWEEP_GAP 4                     // blank gap width ahead of cursor

uint16_t rttHist[HIST];
uint8_t  stHist[HIST];
int   sweepX = 0;
bool  filled = false;
int   yFloor = 0, yCeil = 40;
int   gPrevX=-1, gPrevY=-1; bool gPrevValid=false;

volatile bool newProbe=false, newNet=false;
probe_t  lastProbe = {MSG_PROBE,0,0,2};
netinfo_t lastNet;
char curIp[16]="", curCountry[4]="", curAsn[48]="";

uint8_t lastMac[6];
int lastRssi=0;
uint32_t pktCount=0, missed=0, prevSeq=0;
bool haveSeq=false;
unsigned long lastRxMs=0, lastIntervalMs=0;

bool debugMode=false, forceRedraw=false;
unsigned long ledOffAt=0;

#define TICK_N 20
uint16_t tickVals[TICK_N]; uint8_t tickSt[TICK_N]; int tickHead=0, tickCount=0;

// ---- receive ----
void handleRx(const uint8_t *mac, const uint8_t *data, int len){
  if (len<1) return;
  memcpy((void*)lastMac, mac, 6);
  unsigned long now=millis();
  if (data[0]==MSG_PROBE && len==(int)sizeof(probe_t)){
    memcpy(&lastProbe, data, sizeof(probe_t));
    lastIntervalMs = now-lastRxMs; pktCount++;
    if (haveSeq && lastProbe.seq>prevSeq+1) missed += (lastProbe.seq-prevSeq-1);
    prevSeq=lastProbe.seq; haveSeq=true; newProbe=true;
  } else if (data[0]==MSG_NETINFO && len==(int)sizeof(netinfo_t)){
    memcpy(&lastNet, data, sizeof(netinfo_t)); newNet=true;
  }
  lastRxMs=now;
}
#if ESP_ARDUINO_VERSION >= ESP_ARDUINO_VERSION_VAL(3,0,0)
void onRecv(const esp_now_recv_info_t *info, const uint8_t *data, int len){ lastRssi=info->rx_ctrl->rssi; handleRx(info->src_addr,data,len); }
#else
void onRecv(const uint8_t *mac, const uint8_t *data, int len){ lastRssi=0; handleRx(mac,data,len); }
#endif

String macStr(const uint8_t*m){ char b[18]; sprintf(b,"%02X:%02X:%02X:%02X:%02X:%02X",m[0],m[1],m[2],m[3],m[4],m[5]); return String(b); }

// ---- autoscale: percentile ceiling (ignores lone spikes, follows real rises) ----
static int cmp_u16(const void*a,const void*b){ return (int)(*(const uint16_t*)a)-(int)(*(const uint16_t*)b); }
void computeScale(int &nf,int &nc){
  static uint16_t tmp[HIST];
  int n=0; uint16_t mn=65535;
  int cnt = filled?HIST:(sweepX+1);
  for (int i=0;i<cnt;i++){ if (stHist[i]==0){ tmp[n++]=rttHist[i]; if(rttHist[i]<mn)mn=rttHist[i]; } }
  if (n==0){ nf=0; nc=40; return; }
  qsort(tmp,n,sizeof(uint16_t),cmp_u16);
  int p = tmp[(int)(n*0.95)];                 // 95th percentile
  int ceil=(int)(p*1.15)+2;
  int step = ceil<=50?5 : ceil<=100?10 : ceil<=200?20 : 25;
  ceil=((ceil+step-1)/step)*step;
  if (ceil>RTT_CAP) ceil=RTT_CAP;
  int floor=(mn/step)*step;
  if (floor<0) floor=0;
  if (ceil-floor<step) ceil=floor+step;
  nf=floor; nc=ceil;
}
int mapY(uint16_t rtt){
  int v=rtt; if(v>yCeil)v=yCeil; if(v<yFloor)v=yFloor;
  long span=yCeil-yFloor; if(span<1)span=1;
  int y=PLOT_Y1-(int)((long)(v-yFloor)*(PLOT_H-1)/span);
  if(y<PLOT_Y0)y=PLOT_Y0; if(y>PLOT_Y1)y=PLOT_Y1;
  return y;
}

void drawYLabels(){
  tft.setTextSize(1); tft.setTextColor(COL_AXIS,COL_PLOT_BG);
  tft.setCursor(PLOT_X0+2,PLOT_Y0+1);   tft.print(yCeil);  tft.print("ms ");
  tft.setCursor(PLOT_X0+2,PLOT_Y1-9);   tft.print(yFloor); tft.print("ms ");
}

void drawColumn(int col){
  int x=PLOT_X0+col;
  tft.drawFastVLine(x,PLOT_Y0,PLOT_H,COL_PLOT_BG);
  if (stHist[col]!=0){ tft.drawFastVLine(x,PLOT_Y0,PLOT_H,COL_FAIL); gPrevValid=false; }
  else {
    int y=mapY(rttHist[col]);
    if (gPrevValid && gPrevX==x-1) tft.drawLine(gPrevX,gPrevY,x,y,COL_TRACE); else tft.drawPixel(x,y,COL_TRACE);
    gPrevX=x; gPrevY=y; gPrevValid=true;
  }
}

void fullGraphRedraw(){
  tft.fillRect(PLOT_X0,PLOT_Y0,PLOT_W,PLOT_H,COL_PLOT_BG);
  int cnt = filled?HIST:(sweepX+1);
  int lpx=-1,lpy=-1; bool lpv=false;
  for (int c=0;c<cnt;c++){
    bool inGap=false;
    for (int g=1;g<=SWEEP_GAP;g++) if (c==((sweepX+g)%HIST)){ inGap=true; break; }
    if (inGap){ lpv=false; continue; }
    int x=PLOT_X0+c;
    if (stHist[c]!=0){ tft.drawFastVLine(x,PLOT_Y0,PLOT_H,COL_FAIL); lpv=false; }
    else {
      int y=mapY(rttHist[c]);
      if (lpv && lpx==x-1) tft.drawLine(lpx,lpy,x,y,COL_TRACE); else tft.drawPixel(x,y,COL_TRACE);
      lpx=x; lpy=y; lpv=true;
    }
  }
  drawYLabels();
  gPrevValid=false;
}

void onSample(uint16_t rtt,uint8_t st){
  int col=sweepX;
  rttHist[col]=rtt; stHist[col]=st;
  int nf,nc; computeScale(nf,nc);
  bool rescaled = (nf!=yFloor || nc!=yCeil);
  if (rescaled){ yFloor=nf; yCeil=nc; }
  for (int g=1;g<=SWEEP_GAP;g++){ int gc=(col+g)%HIST; tft.drawFastVLine(PLOT_X0+gc,PLOT_Y0,PLOT_H,COL_PLOT_BG); }
  if (rescaled) fullGraphRedraw(); else drawColumn(col);
  sweepX++; if(sweepX>=HIST){ sweepX=0; filled=true; gPrevValid=false; }
}

void pushTick(uint16_t v,uint8_t st){ tickVals[tickHead]=v; tickSt[tickHead]=st; tickHead=(tickHead+1)%TICK_N; if(tickCount<TICK_N)tickCount++; }

void drawTicker(){
  tft.fillRect(0,TICK_Y,320,TICK_H,COL_TICK_BG);
  tft.setTextSize(2);
  int x=4, y=TICK_Y+2;
  int shown = tickCount<TICK_N?tickCount:TICK_N;
  for (int i=0;i<shown;i++){
    int idx=(tickHead-1-i+TICK_N*2)%TICK_N;      // newest first (left)
    char buf[8];
    if (tickSt[idx]==0) sprintf(buf,"%u",tickVals[idx]); else strcpy(buf,"x");
    int w=strlen(buf)*12;
    if (x+w>316) break;
    tft.setTextColor(i==0?COL_TICK_CUR:COL_TICK_TXT, COL_TICK_BG);
    tft.setCursor(x,y); tft.print(buf);
    x+=w+10;
  }
}

void drawHeaderIP(){
  tft.fillRect(0,IP_Y,320,24,COL_BG);
  tft.setTextSize(3); tft.setTextColor(COL_IP,COL_BG);
  tft.setCursor(2,IP_Y); tft.print(curIp[0]?curIp:"(no ip)");
}
void drawHeaderGeo(){
  tft.fillRect(0,GEO_Y,320,18,COL_BG);
  tft.setTextSize(2); tft.setTextColor(COL_GEO,COL_BG);
  char line[72]; snprintf(line,sizeof(line),"%s %s", curCountry, curAsn);
  const int MAXCH=26;                             // whole words that fit @ size2
  if ((int)strlen(line)>MAXCH){ line[MAXCH]=0; char* sp=strrchr(line,' '); if(sp)*sp=0; }
  tft.setCursor(2,GEO_Y); tft.print(line[0]?line:" ");
}

void applyNet(){
  strncpy(curIp,lastNet.ip,sizeof(curIp)-1); curIp[sizeof(curIp)-1]=0;
  strncpy(curCountry,lastNet.country,sizeof(curCountry)-1); curCountry[sizeof(curCountry)-1]=0;
  strncpy(curAsn,lastNet.asn,sizeof(curAsn)-1); curAsn[sizeof(curAsn)-1]=0;
}

void drawChrome(){
  tft.fillScreen(COL_BG);
  tft.fillRect(PLOT_X0,PLOT_Y0,PLOT_W,PLOT_H,COL_PLOT_BG);
  tft.fillRect(0,TICK_Y,320,TICK_H,COL_TICK_BG);
  drawHeaderIP(); drawHeaderGeo(); drawYLabels();
}

void drawDebug(){
  tft.fillScreen(COL_BG);
  tft.setTextColor(0xFFE0); tft.setTextSize(2); tft.setCursor(6,6); tft.println("DEBUG / raw ESP-NOW");
  tft.setTextColor(COL_IP); tft.setTextSize(1); int y=34;
  tft.setCursor(6,y); tft.print("from  "); tft.println(macStr(lastMac)); y+=12;
  tft.setCursor(6,y); tft.print("rssi  "); tft.print(lastRssi); tft.println(" dBm"); y+=12;
  tft.setCursor(6,y); tft.print("pkts  "); tft.print(pktCount); tft.print("  missed "); tft.println(missed); y+=12;
  tft.setCursor(6,y); tft.print("rate  "); tft.print(lastIntervalMs?1000.0/lastIntervalMs:0,2); tft.println(" /s"); y+=16;
  tft.setCursor(6,y); tft.print("PROBE seq "); tft.print(lastProbe.seq);
    tft.print(" rtt "); tft.print(lastProbe.rtt_ms); tft.print(" st "); tft.print(lastProbe.status);
    tft.print(" ("); tft.print(statusLabel(lastProbe.status)); tft.println(")"); y+=12;
  tft.setCursor(6,y); tft.print("scale "); tft.print(yFloor); tft.print(".."); tft.print(yCeil); tft.println(" ms"); y+=16;
  tft.setCursor(6,y); tft.print("ip  "); tft.println(curIp[0]?curIp:"-"); y+=12;
  tft.setCursor(6,y); tft.print("cc  "); tft.println(curCountry[0]?curCountry:"-"); y+=12;
  tft.setCursor(6,y); tft.print("as  "); tft.println(curAsn[0]?curAsn:"-");
}

void setup(){
  Serial.begin(115200); delay(300);
  pinMode(LED_R,OUTPUT); pinMode(LED_G,OUTPUT); pinMode(LED_B,OUTPUT); ledOff();
  pinMode(BTN,INPUT_PULLUP);
  pinMode(TFT_BL,OUTPUT); digitalWrite(TFT_BL,HIGH);
  SPI.begin(14,12,13,15);
  tft.init(240,320); tft.setRotation(1);
  uint8_t madctl=ST77XX_MADCTL_MX|ST77XX_MADCTL_MY|ST77XX_MADCTL_MV|ST77XX_MADCTL_RGB; // 0xE0
  tft.sendCommand(ST77XX_MADCTL,&madctl,1);
  tft.invertDisplay(false);     // this panel shows black-as-white otherwise; flip to true if colours look wrong

  drawChrome();
  tft.setTextSize(1); tft.setTextColor(COL_AXIS,COL_PLOT_BG);
  tft.setCursor(PLOT_X0+6,PLOT_Y0+PLOT_H/2-4); tft.print("waiting for packets...");

  WiFi.mode(WIFI_STA); WiFi.disconnect();
  esp_wifi_set_channel(ESPNOW_CHANNEL,WIFI_SECOND_CHAN_NONE);
  Serial.print("RX MAC: "); Serial.println(WiFi.macAddress());
  if (esp_now_init()!=ESP_OK){ tft.fillScreen(COL_FAIL); return; }
  esp_now_register_recv_cb(onRecv);
}

void loop(){
  static unsigned long lastToggle=0;
  if (digitalRead(BTN)==LOW && millis()-lastToggle>250){ lastToggle=millis(); debugMode=!debugMode; forceRedraw=true; }

  if (forceRedraw){ forceRedraw=false;
    if (debugMode) drawDebug();
    else { drawChrome(); if (filled||sweepX>0) fullGraphRedraw(); drawTicker(); }
  }

  if (newProbe){ newProbe=false;
    pushTick(lastProbe.rtt_ms,lastProbe.status);
    if (debugMode) drawDebug();
    else { onSample(lastProbe.rtt_ms,lastProbe.status); drawTicker(); }
    ledGreen(true); ledOffAt=millis()+80;
  }
  if (newNet){ newNet=false; applyNet(); if(!debugMode){ drawHeaderIP(); drawHeaderGeo(); } }

  if (ledOffAt && millis()>ledOffAt){ ledGreen(false); ledOffAt=0; }
  ledRed(lastRxMs && millis()-lastRxMs>5000);
}

